package ru.ceh.mobile;
import android.app.*;
import android.os.*;
import android.content.*;
import android.net.Uri;
import android.provider.Settings;
import android.webkit.*;
import android.webkit.CookieManager;
import android.widget.*;
import android.view.View;
import android.print.PrintManager;
import java.net.*;
import javax.net.ssl.HttpsURLConnection;
import java.io.*;
import java.security.MessageDigest;
import org.json.JSONObject;

/** Installed Android 11+ client; credentials stay in HttpOnly server cookies. */
public class MainActivity extends Activity {
 private static final int VERSION=1, PICK_FILE=100;
 private WebView browser;private String base="",expectedHash="";private long downloadId=-1;private Uri verifiedUpdate;
 private Uri captureUri;private ValueCallback<Uri[]> chooser;private boolean mandatory=false;
 private final BroadcastReceiver downloaded=new BroadcastReceiver(){public void onReceive(Context context,Intent intent){if(intent.getLongExtra(DownloadManager.EXTRA_DOWNLOAD_ID,-2)==downloadId)verifyAndInstall();}};
 public void onCreate(Bundle saved){super.onCreate(saved);base=getPreferences(0).getString("server","");
  LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);LinearLayout tools=new LinearLayout(this);
  add(tools,"Главная",()->browser.loadUrl(base+"/mobile"));add(tools,"Печать",()->{PrintManager pm=(PrintManager)getSystemService(PRINT_SERVICE);pm.print("Цех",browser.createPrintDocumentAdapter("Цех"),null);});add(tools,"Обновить",()->{if(verifiedUpdate!=null)install();else checkUpdate(true);});add(tools,"Сервер",()->settings());root.addView(tools);
  browser=new WebView(this);root.addView(browser,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);
  WebSettings ws=browser.getSettings();ws.setJavaScriptEnabled(true);ws.setDomStorageEnabled(true);ws.setAllowFileAccess(false);ws.setAllowContentAccess(false);ws.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);ws.setSupportMultipleWindows(false);
  CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(browser,false);WebView.setWebContentsDebuggingEnabled(false);
  browser.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){Uri u=request.getUrl();if(sameOrigin(u))return false;if("https".equals(u.getScheme())||"tel".equals(u.getScheme())){try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception ignored){} }return true;}public void onPageFinished(WebView view,String url){CookieManager.getInstance().flush();}public void onReceivedError(WebView view,WebResourceRequest request,WebResourceError error){if(request.isForMainFrame())message("Нет связи с сервером. Проверьте интернет и VPN, затем нажмите «Главная». Неподтверждённые документы не проводите повторно с новыми данными.");}});
  browser.setWebChromeClient(new WebChromeClient(){public boolean onShowFileChooser(WebView view,ValueCallback<Uri[]> callback,FileChooserParams params){if(chooser!=null)chooser.onReceiveValue(null);chooser=callback;Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT);pick.addCategory(Intent.CATEGORY_OPENABLE);pick.setType("image/*");try{Intent camera=new Intent(android.provider.MediaStore.ACTION_IMAGE_CAPTURE);String name=java.util.UUID.randomUUID().toString()+".jpg";captureUri=Uri.parse("content://ru.ceh.mobile.capture/capture/"+name);camera.putExtra(android.provider.MediaStore.EXTRA_OUTPUT,captureUri);camera.setClipData(ClipData.newRawUri("capture",captureUri));camera.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);Intent choice=Intent.createChooser(pick,"Фото документа");choice.putExtra(Intent.EXTRA_INITIAL_INTENTS,new Intent[]{camera});startActivityForResult(choice,PICK_FILE);}catch(Exception e){chooser.onReceiveValue(null);chooser=null;}return true;}});
  browser.setDownloadListener((url,agent,disposition,mime,length)->{Uri u=Uri.parse(url);if(!sameOrigin(u))return;DownloadManager.Request r=new DownloadManager.Request(u);r.addRequestHeader("Cookie",CookieManager.getInstance().getCookie(url));r.addRequestHeader("User-Agent",agent);r.setMimeType(mime);r.setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED);r.setDestinationInExternalPublicDir(Environment.DIRECTORY_DOWNLOADS,URLUtil.guessFileName(url,disposition,mime));((DownloadManager)getSystemService(DOWNLOAD_SERVICE)).enqueue(r);message("Документ сохраняется в Загрузки");});
  IntentFilter filter=new IntentFilter(DownloadManager.ACTION_DOWNLOAD_COMPLETE);if(Build.VERSION.SDK_INT>=33)registerReceiver(downloaded,filter,Context.RECEIVER_NOT_EXPORTED);else registerReceiver(downloaded,filter);
  File captures=new File(getCacheDir(),"capture");File[] old=captures.listFiles();if(old!=null)for(File file:old)if(file.lastModified()<System.currentTimeMillis()-86400000L)file.delete();
  if(base.isEmpty())settings();else{browser.loadUrl(base+"/mobile");checkUpdate(false);}
 }
 private void add(LinearLayout row,String text,Runnable action){Button b=new Button(this);b.setText(text);b.setTextSize(11);row.addView(b,new LinearLayout.LayoutParams(0,-2,1));b.setOnClickListener(v->action.run());}
 private boolean sameOrigin(Uri uri){Uri host=Uri.parse(base);return "https".equals(uri.getScheme())&&host.getHost()!=null&&host.getHost().equalsIgnoreCase(uri.getHost())&&uri.getPort()==host.getPort();}
 private void settings(){EditText address=new EditText(this);address.setSingleLine();address.setHint("https://ваш-сервер.ts.net");address.setText(base);new AlertDialog.Builder(this).setTitle("Адрес общей базы").setMessage("Введите HTTPS-адрес, подготовленный на серверном ПК. При смене сервера вход выполняется заново.").setView(address).setNegativeButton("Отмена",null).setPositiveButton("Подключить",(d,w)->{String value=address.getText().toString().trim().replaceAll("/+$","");try{URI uri=new URI(value);if(!"https".equals(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null||uri.getQuery()!=null||uri.getFragment()!=null||(uri.getPath()!=null&&!uri.getPath().isEmpty()))throw new Exception();}catch(Exception e){message("Нужен HTTPS-адрес без логина, пути и параметров");return;}if(!base.equals(value)){CookieManager.getInstance().removeAllCookies(null);browser.clearCache(true);WebStorage.getInstance().deleteAllData();}base=value;getPreferences(0).edit().putString("server",base).apply();browser.loadUrl(base+"/mobile");checkUpdate(false);}).show();}
 private void message(String text){runOnUiThread(()->Toast.makeText(this,text,Toast.LENGTH_LONG).show());}
 private void checkUpdate(boolean visible){if(base.isEmpty()){settings();return;}new Thread(()->{try{HttpsURLConnection conn=(HttpsURLConnection)new URL(base+"/api/client-version").openConnection();conn.setConnectTimeout(10000);conn.setReadTimeout(10000);String data;try(InputStream in=conn.getInputStream()){ByteArrayOutputStream buffer=new ByteArrayOutputStream();byte[] part=new byte[4096];int n;while((n=in.read(part))!=-1){buffer.write(part,0,n);if(buffer.size()>65536)throw new IOException("Слишком большой ответ");}data=buffer.toString("UTF-8");}finally{conn.disconnect();}JSONObject update=new JSONObject(data).getJSONObject("android");int latest=update.getInt("latest"),minimum=update.getInt("minimum");mandatory=minimum>VERSION;if(latest<=VERSION){if(visible)message("Установлена актуальная версия 0.6.0");return;}String url=update.optString("url"),hash=update.optString("sha256");if(!url.startsWith("https://")||!hash.matches("[a-fA-F0-9]{64}"))throw new Exception("Администратор ещё не опубликовал проверяемый APK");runOnUiThread(()->{if(mandatory)browser.setVisibility(View.GONE);AlertDialog.Builder b=new AlertDialog.Builder(this).setTitle("Обновление Цех").setMessage("Доступна версия "+latest+". APK будет проверен по SHA-256, затем Android запросит подтверждение установки.").setPositiveButton("Скачать",(d,w)->download(url,hash)).setCancelable(!mandatory);if(!mandatory)b.setNegativeButton("Позже",null);b.show();});}catch(Exception e){if(visible)message("Проверка обновления: "+e.getMessage());}}).start();}
 private void download(String url,String hash){expectedHash=hash.toLowerCase(java.util.Locale.ROOT);File old=new File(getExternalFilesDir(Environment.DIRECTORY_DOWNLOADS),"ceh-update.apk");if(old.exists())old.delete();DownloadManager.Request r=new DownloadManager.Request(Uri.parse(url));r.setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE);r.setDestinationInExternalFilesDir(this,Environment.DIRECTORY_DOWNLOADS,"ceh-update.apk");downloadId=((DownloadManager)getSystemService(DOWNLOAD_SERVICE)).enqueue(r);}
 private void verifyAndInstall(){new Thread(()->{try{DownloadManager manager=(DownloadManager)getSystemService(DOWNLOAD_SERVICE);Uri uri=manager.getUriForDownloadedFile(downloadId);if(uri==null)throw new IOException("Загрузка не завершена");MessageDigest md=MessageDigest.getInstance("SHA-256");try(InputStream in=getContentResolver().openInputStream(uri)){byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1)md.update(buffer,0,n);}StringBuilder hash=new StringBuilder();for(byte b:md.digest())hash.append(String.format("%02x",b&255));if(!expectedHash.equals(hash.toString())){manager.remove(downloadId);throw new IOException("Контрольная сумма APK не совпадает");}verifiedUpdate=uri;runOnUiThread(()->install());}catch(Exception e){message("Обновление не установлено: "+e.getMessage());}}).start();}
 private void install(){if(verifiedUpdate==null)return;if(!getPackageManager().canRequestPackageInstalls()){startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName())));message("Разрешите обновления для Цех, затем нажмите «Обновить» ещё раз");return;}Intent intent=new Intent(Intent.ACTION_VIEW);intent.setDataAndType(verifiedUpdate,"application/vnd.android.package-archive");intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(intent);}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==PICK_FILE&&chooser!=null){Uri selected=result==RESULT_OK?(data!=null&&data.getData()!=null?data.getData():captureUri):null;if(captureUri!=null)revokeUriPermission(captureUri,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);chooser.onReceiveValue(selected==null?null:new Uri[]{selected});captureUri=null;chooser=null;}}
 public void onBackPressed(){if(browser.canGoBack())browser.goBack();else super.onBackPressed();}
 protected void onDestroy(){unregisterReceiver(downloaded);if(chooser!=null)chooser.onReceiveValue(null);browser.destroy();super.onDestroy();}
}
